items = json.loads(SRC)

# ---------- 枚举硬守卫（§3.114a） ----------
bad_t = {x['track'] for x in items} - VALID_TRACK
bad_c = {x['category'] for x in items} - VALID_CAT
bad_d = {x['direction'] for x in items} - VALID_DIR
if bad_t or bad_c or bad_d:
    raise SystemExit(f"⚠️ 非法枚举值 track={bad_t} category={bad_c} direction={bad_d}")

# ---------- §3.129d：标题前 24 字唯一性守卫（规则表键碰撞前置拦截） ----------
pref = [x['title'][:24] for x in items]
if len(set(pref)) != len(pref):
    dup = [p for p in set(pref) if pref.count(p) > 1]
    raise SystemExit(f"⚠️ §3.129d 标题前 24 字碰撞：{dup}")

# ---------- 逐条补齐字段 ----------
for i, x in enumerate(items, 1):
    x['idx'] = i
    x['window'] = WIN
    x.setdefault('source_url', '')
    if not x.get('source_url'):
        print(f"  ⚠️ 第 {i} 条无 source_url（按约定留空）")

json.dump(items, open(OUT, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
