print('赛道分布:', dict(Counter(x['track'] for x in items)))
print('方向分布:', dict(Counter(x['direction'] for x in items)))
print('分类分布:', dict(Counter(x['category'] for x in items)))
print('source_url 覆盖:', sum(1 for x in items if x.get('source_url')), '/', len(items))
print('窗口:', WIN)
